// Country is a text input - let's type it
await page.type({ ref: "e24", text: "United States", clear: true })
// Wait a moment for any autocomplete
await wait({ waitTime: 1 })

// The country is a select element - use the select API
await page.select({ ref: "e24", values: ["United States"] })
await wait({ waitTime: 1 })

var snap = await page.snapshot()
console.log("--- Full outline ---")
console.log(snap.snapshot.outline())
console.log("--- Checking Country specifically ---")
var hits = snap.snapshot.grep("Country", { context: 3 })
console.log(hits)
console.log("--- Checking United States ---")
